@page "/catalog"
@namespace sv_c6f455f0078a4ed6b1377c2256d492b5.Components.Pages.Catalog
@using sv_c6f455f0078a4ed6b1377c2256d492b5
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page">
    <CatalogFilterPanel Categories="_categories"
                        OnFilterApplied="HandleFilterApplied"
                        OnFilterCleared="HandleFilterCleared" />

    <main class="catalog-main">
        @if (_error is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @_error
            </div>
        }
        else if (_isLoading)
        {
            <div class="loading-indicator">
                <p>Loading products...</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_totalCount"
                            Page="@_currentPage"
                            PageSize="@_pageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="@_products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="@_currentPage"
                               TotalCount="@_totalCount"
                               PageSize="@_pageSize"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    /// <summary>
    /// Raised when a product card is clicked, allowing the parent/layout to navigate to a detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private List<Product> _products = new();
    private ProductFilter _currentFilter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _pageSize = 12;
    private int _totalCount;
    private bool _isLoading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        _isLoading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, _pageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            var result = await productsTask;
            _products = result.Items;
            _totalCount = result.TotalCount;
        }
        catch (Exception ex)
        {
            _error = $"Failed to load products. Please try again. ({ex.Message})";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task SearchAsync()
    {
        _isLoading = true;
        _error = null;

        try
        {
            var result = await ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, _pageSize);
            _products = result.Items;
            _totalCount = result.TotalCount;
        }
        catch (Exception ex)
        {
            _error = $"Failed to load products. Please try again. ({ex.Message})";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _currentFilter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFilterCleared()
    {
        _currentFilter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

